@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:LinkRole ;
                    schema1:linkRelationship "implementationSoftware" ] ;
            sh:resultMessage "A schema:LinkRole should carry a schema:target naming what is linked to." ;
            sh:resultPath schema1:target ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ a sh:PropertyShape ;
                    sh:message "A schema:LinkRole should carry a schema:target naming what is linked to." ;
                    sh:minCount 1 ;
                    sh:path schema1:target ;
                    sh:severity sh:Warning ] ] .

